const input = $json.body;

const errors = [];

if (!input) {
  errors.push("Missing request body");
}

if (typeof input?.content !== "string") {
  errors.push("content must be a string");
}

if (typeof input?.content === "string" && input.content.trim() === "") {
  errors.push("content cannot be empty");
}

if (typeof input?.filename !== "string" || input.filename.trim() === "") {
  errors.push("filename is required");
}

if (typeof input?.filepath !== "string" || input.filepath.trim() === "") {
  errors.push("filepath is required");
}

if (!Number.isFinite(input?.timestamp)) {
  errors.push("timestamp must be a number");
}

if (errors.length > 0) {
  return [
    {
      json: {
        valid: false,
        errors,
        source: "obsidian",
      },
    },
  ];
}

return [
  {
    json: {
      valid: true,
      source: "obsidian",
      note: {
        content: input.content,
        filename: input.filename,
        filepath: input.filepath,
        timestamp: input.timestamp,
        createdAt: input.createdAt,
        modifiedAt: input.modifiedAt,
        attachments: input.attachments ?? [],
      },
    },
  },
];

return [
  {
    json: {
      success: false,
      error: "Invalid Obsidian payload",
      details: $json.errors ?? [],
    },
  },
];

const note = $json.note;

return [
  {
    json: {
      source: "obsidian",

      note: {
        filename: note.filename,
        filepath: note.filepath,
        content: note.content,

        timestamps: {
          timestamp: note.timestamp,
          createdAt: note.createdAt,
          modifiedAt: note.modifiedAt,
        },

        attachments: note.attachments ?? [],
      },
    },
  },
];

const results = [];

for (const item of $input.all()) {
  const text = item.json.content?.parts?.[0]?.text;

  if (!text) {
    throw new Error(
      'Gemini response does not contain content.parts[0].text'
    );
  }

  let cleaned = text.trim();

  // Remove Markdown code fences if Gemini returns ```json ... ```
  cleaned = cleaned
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  let parsed;

  try {
    parsed = JSON.parse(cleaned);
  } catch (error) {
    throw new Error(
      `Invalid JSON returned by Gemini: ${error.message}`
    );
  }

  results.push({
    json: parsed
  });
}

return results;

const data = $json;

const requiredFields = [
  "summary",
  "category",
  "topics",
  "key_concepts",
  "actions",
  "tags"
];

const errors = [];

// 1. Check required fields
for (const field of requiredFields) {
  if (!(field in data)) {
    errors.push(`Missing field: ${field}`);
  }
}

// 2. Check types
if ("summary" in data && typeof data.summary !== "string") {
  errors.push("summary must be a string");
}

if ("category" in data && typeof data.category !== "string") {
  errors.push("category must be a string");
}

const arrayFields = [
  "topics",
  "key_concepts",
  "actions",
  "tags"
];

for (const field of arrayFields) {
  if (field in data && !Array.isArray(data[field])) {
    errors.push(`${field} must be an array`);
  }
}

// 3. Check for unexpected fields
const allowedFields = new Set(requiredFields);

for (const field of Object.keys(data)) {
  if (!allowedFields.has(field)) {
    errors.push(`Unexpected field: ${field}`);
  }
}

// 4. Return validation result
return [
  {
    json: {
      ...data,
      validation: {
        valid: errors.length === 0,
        errors
      }
    }
  }
];

